{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (0.00–0.67) and model shows overestimation, especially after recent spikes.",
    "Increase forecast sensitivity to recent low prices when sentiment is negative (e.g., -0.25), indicating potential mean reversion.",
    "Apply a lag correction: if true price is higher than forecasted 3–5 days ago, reduce current forecast by 1–2% to avoid overshoot.",
    "When sentiment is neutral (0.00) and forecast consistently underestimates true price, add a 0.5–1.5% upward bias for the next 3–5 days.",
    "Avoid overreacting to short-term sentiment swings; if sentiment shifts rapidly, anchor forecast to 14-day moving average to reduce noise.",
    "For high sentiment (0.67+), reduce forecast volatility by 20–30% to prevent over-optimism-driven overshoots."
  ]
}
